// Local replacement for the panels' logical data routes. No HTTP API fallback.
import { chainClient, ChainDataError, checkAbort } from './client.js';
import { gameState, playerState, playerAddress, uint, bigintJSON, scoreBreakdown } from './state.js';
import { ticketInventory, foilInventory } from './tickets.js';
import { bingoCandidates, farFutureQueue } from './positions.js';
import { cachedEvents } from './event-store.js';
import { decodePackedBoons } from '../app/boons.js';
import { rememberCompletedJackpot } from '../app/jackpot-cache.js';

export async function readChainRoute(path, { signal, client = chainClient() } = {}) {
  checkAbort(signal);
  const url = new URL(path, 'https://local.invalid');
  if (url.origin !== 'https://local.invalid') throw new ChainDataError('Only local data routes are supported.', 'INVALID_REQUEST');
  const parts = url.pathname.split('/').filter(Boolean); const q = url.searchParams;
  const s = await client.snapshot({ signal });
  let result;
  if (parts[0] === 'health') result = { status: 'ok', source: 'chain', chainId: client.chain.id, blockNumber: s.block.number, blockHash: s.block.hash };
  else if (url.pathname === '/game/state') result = await gameState(s);
  else if (parts[0] === 'player') {
    const player = playerAddress(parts[1]); const route = parts.slice(2).join('/');
    if (!route) {
      if (q.has('day') && uint(q.get('day')) !== Number(await s.field('GAME', 'dailyIdx'))) {
        const { readHistoryRoute } = await import('./history.js'); result = await readHistoryRoute(s, url, { signal });
      } else {
        result = await playerState(s, player);
        if (q.has('claims') || q.has('inventory') || q.has('pending')) { const { extendPlayer } = await import('./player.js'); result = await extendPlayer(s,result,q,signal); }
      }
    }
    else if (route === 'activity-score') {
      if (q.has('day') && uint(q.get('day')) !== Number(await s.field('GAME', 'dailyIdx'))) throw new ChainDataError('A past activity score is not available from current storage.', 'HISTORICAL_STATE_UNAVAILABLE');
      const b = await s.call('GAME_LENS', 'activityScoreBreakdown', [client.address('GAME'), player]);
      result = { address: player, player, scoreBps: Number(b.total), breakdown: scoreBreakdown(b), blockNumber: String(s.block.number) };
    }
    else if (route === 'tickets/by-trait') result = await ticketInventory(s, player, uint(q.get('level')), { signal });
    else if (route === 'foil') result = await foilInventory(s, player, uint(q.get('level')), { signal });
    else if (route === 'bingos') result = await bingoCandidates(s, player, { level: q.has('level') ? uint(q.get('level')) : undefined, signal });
    else if (route === 'far-future-queue') result = await farFutureQueue(s, player, { signal });
    else if (route === 'operators' || route === 'approvers') {
      const outgoing = route === 'operators'; const mine = outgoing ? 'owner' : 'operator'; const other = outgoing ? 'operator' : 'owner';
      const logs = await cachedEvents(s, 'GAME', 'OperatorApproval', { [mine]: player }, { signal });
      const latest = new Map(logs.map(log => [log.args[other].toLowerCase(), log]));
      result = { [mine]: player, [route]: [...latest.values()].filter(log => log.args.approved).reverse()
        .map(log => ({ [other]: log.args[other].toLowerCase(), blockNumber: String(log.blockNumber) })) };
    }
    else if (parts[2] === 'boons' && uint(parts[3]) === Number(await s.field('GAME', 'dailyIdx'))) {
      const packed = await s.call('GAME', 'boonPacked', [player]);
      result = { day: uint(parts[3]), address: player, boons: decodePackedBoons(packed.slot0, packed.slot1, parts[3]) };
    }
  }
  if (result === undefined) {
    const { readHistoryRoute } = await import('./history.js');
    result = await readHistoryRoute(s, url, { signal });
  }
  if (result === undefined) throw new ChainDataError(`No chain reader for ${url.pathname}.`, 'UNSUPPORTED_READ');
  await s.verify(signal); checkAbort(signal);
  // Exact roll/winner routes share this composed draw. Save it only after the
  // snapshot's chain verification, so every replay fragment can reuse it.
  for (const [day, draw] of s.completedJackpots ?? []) {
    if (s.savedJackpotDays?.has(day)) continue;
    if (rememberCompletedJackpot(draw)) {
      s.savedJackpotDays ??= new Set();
      s.savedJackpotDays.add(day);
    }
  }
  return bigintJSON(result);
}
